  private constructor(props: EmailProps) {
    super(props);
  }

  protected validate(props: EmailProps): void {
    if (!isValidEmail(props.value)) {
      throw new ArgumentInvalidException('Invalid email format');
    }
  }

  public static create(value: string): Result<Email, string> {
    try {
      return Result.ok(new Email({ value: value.trim().toLowerCase() }));
    } catch (error) {
      return Result.err(error instanceof Error ? error.message : String(error));
    }
  }

  public getValue(): string {
    return this.props.value;
  }
}

