    const row = await this.prisma.entity.findUnique({ where: { id } });
    if (!row) {
      return Result.err('Entity not found');
    }
    return Result.ok(this.mapper.toDomain(row));
  } catch (error) {
    return Result.err(`Database error: ${error instanceof Error ? error.message : String(error)}`);
  }
}

